-- seed_finalized_coa_demo_company_0002.sql
-- [feature-spec.md decision #17] Apply schema.sql first, then this file.
-- Chart rows go into coa_template (no company id). seed_company_coa copies
-- them onto the demo company ...0002. Re-running does not duplicate accounts.
-- [feature-spec.md decision #6] Demo company fixed UUID for seed only.
-- [feature-spec.md decision #16] 3100 Retained Earnings is_system_account = true.

BEGIN;

VALUES ('00000000-0000-0000-0000-000000000002', 'Demo Company (Finalized COA Seed)', 'AED', false, 1)
ON CONFLICT (id) DO NOTHING;

VALUES ('00000000-0000-0000-0000-000000000002')
ON CONFLICT (company_id) DO NOTHING;


SELECT public.seed_company_coa('00000000-0000-0000-0000-000000000002');

COMMIT;
